    endMethod
endClass

class Square extends Shape
    private define side as integer;

    method constructor(aSide as integer)
        this.side <- aSide;
    endMethod

    public method Area() as real
        return this.side * this.side;
    endMethod
endClass

class Circle extends Shape
    private define radius as integer;

    method constructor(aRadius as integer)
        this.radius <- aRadius;
    endMethod

    public method Area() as real
        return this.radius * this.radius * 3.14;
    endMethod
endClass

class IsoscelesTriangle extends Shape
    private define base as integer;

    method constructor(aBase as integer)
        this.base <- aBase;
    endMethod

    public method Area() as real
        return this.base * this.base / 2;
    endMethod
endClass

algorithm ComputePolymorphicArea
    define kind as integer;
    define measure as integer;
    define shape as Shape;
    read kind;
    read measure;
    if kind = 1 then
        shape <- new Square(measure);
